import{f as i,o as e,c as o,a2 as l}from"./chunks/framework.Cd9rfTEn.js";const p=JSON.parse('{"title":"Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 1 (servicios de red y TIC)","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte1.md","filePath":"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte1.md","lastUpdated":null}'),n={name:"entregables-analisis-diseno/20-casos-prueba/T12-SRV-fichas-verticales-servicios-parte1.md"};function c(t,a,r,d,s,u){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="casos-de-prueba-de-aceptacion-—-t12-srv-—-fichas-verticales-por-servicio-·-parte-1-servicios-de-red-y-tic" tabindex="-1">Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 1 (servicios de red y TIC) <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-t12-srv-—-fichas-verticales-por-servicio-·-parte-1-servicios-de-red-y-tic" aria-label="Permalink to &quot;Casos de prueba de aceptación — T12 SRV — Fichas verticales por servicio · Parte 1 (servicios de red y TIC)&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte1"><code>T12-SRV-fichas-verticales-servicios-parte1.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 0 CP de requisitos funcionales, 58 CP de escenarios ESC y 0 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-SRV-5001 — ESC-SRV-INT-01. La ONT-DEMO-0001 se aplica, SmartOLT confirma <code>activate</code> y la activación queda el 21-11-2026</strong></p><ul><li>Cubre: ESC-SRV-INT-01; RN-TAR-240, RN-TAR-241, RN-TAR-245; relacionados: ESC-TAR-03; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado TEN-001 con INT-100 (valores del <em>seed</em> único de M02 §18 que usa el ejemplo M04 §9.3.9: abono ARS 15.000, promoción PROMO-INT-50x3 = 50 % sobre el abono × 3 ciclos, instalación ARS 20.000 sin descuento, mes adelantado, PRM-TAR-012 = <code>fraction_plus_next</code>, PRM-TAR-016 = <code>false</code>) y Ana Demo con factibilidad favorable</li><li>Cuando La ONT-DEMO-0001 se aplica, SmartOLT confirma <code>activate</code> y la activación queda el 21-11-2026</li><li>Entonces El contrato pasa a <code>active</code> con <code>effectiveStart</code> 21-11-2026; el primer comprobante (diciembre) suma ARS 30.000,00 neto (fracción de noviembre 15.000 × 10/30 = 5.000,00 − 2.500,00 + diciembre 15.000,00 − 7.500,00 + instalación 20.000,00; RN-TAR-240 a 242), el ciclo parcial no consume promoción y obtiene CAE (ESC-TAR-03, DEC-016, DEC-033). Corrección del 05-11-2026 (HUE-SRV-05): antes decía &quot;abono ARS 25.000, promoción 10 % × 3 ciclos, instalación ARS 30.000 … ARS 60.000,00 neto (fracción 8.333,33 − 833,33 + 25.000 − 2.500 + 30.000)&quot;, valores de BASE que M04 conserva solo como casos de prueba de RN-TAR-241 y RN-TAR-245.</li></ul><p><strong>CP-SRV-5002 — ESC-SRV-INT-02. (error) SmartOLT responde <code>timeout</code> tres veces</strong></p><ul><li>Cubre: ESC-SRV-INT-02; RF-TEC-188, RF-POR-071; relacionados: CU-TEC-04; T12 §1.7</li><li>Ola: O3 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato de Ana en <code>pendingInstallation</code> con la OT cerrada en campo</li><li>Cuando SmartOLT responde <code>timeout</code> tres veces</li><li>Entonces EVT-TEC-21 <code>tec.provisioning.failed</code>; el contrato no se activa ni se factura; se crea una tarea manual para el NOC (RF-TEC-188); el socio ve &quot;Instalación realizada – activación en curso&quot; (RF-POR-071; CU-TEC-04).</li></ul><p><strong>CP-SRV-5003 — ESC-SRV-INT-03. Se confirma un pago de ARS 15.000 por Pagos360 (EVT-COB-04)</strong></p><ul><li>Cubre: ESC-SRV-INT-03; relacionados: ESC-MOR-21; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado SUS-DEMO-GRATIS suspendido en modo <code>restricted</code> por una deuda vencida de ARS 15.000</li><li>Cuando Se confirma un pago de ARS 15.000 por Pagos360 (EVT-COB-04)</li><li>Entonces JOB-MOR-07 evalúa la reconexión, M10 emite <code>reactivate</code> y el contrato vuelve a <code>active</code> sin cargo (REACT-DEMO-GRATIS); si T06 falla, el caso queda <code>executionFailed</code> con reintentos y el contrato sigue <code>suspended</code> (ESC-MOR-21, 22).</li></ul><p><strong>CP-SRV-5004 — ESC-SRV-INT-04. El titular pide la baja por el botón público, sin iniciar sesión</strong></p><ul><li>Cubre: ESC-SRV-INT-04; relacionados: ESC-CRM-04, ESC-MOR-27; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado BAJA-DEMO activo con deuda ficticia de ARS 12.500</li><li>Cuando El titular pide la baja por el botón público, sin iniciar sesión</li><li>Entonces Recibe el código en pantalla y por correo en menos de 24 h; no se exige el pago ni se crea un cargo; se emite <code>cat.contract.terminationRequested</code>, OT de retiro de la ONT con plazo de 15 días (PRM-CAT-094); la deuda sigue en M07 (ESC-CRM-04, ESC-MOR-27, DEC-057).</li></ul><p><strong>CP-SRV-5005 — ESC-SRV-INT-05. Pide el cambio a INT-300 (ARS 22.000) el 10-11-2026</strong></p><ul><li>Cubre: ESC-SRV-INT-05; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Ana con INT-100 (ARS 15.000) desde agosto, ciclo mensual</li><li>Cuando Pide el cambio a INT-300 (ARS 22.000) el 10-11-2026</li><li>Entonces <code>cat.contract.planChanged</code> con <code>validFrom</code> 01-12-2026 (DEC-032); M10 emite <code>changePlan</code> con fecha efectiva; noviembre se factura ARS 15.000 y diciembre ARS 22.000.</li></ul><p><strong>CP-SRV-5006 — ESC-SRV-INT-06. (aislamiento) Consulta por ID el contrato INT de Ana (TEN-001) y la ONT-DEMO-0001</strong></p><ul><li>Cubre: ESC-SRV-INT-06; relacionados: ESC-TEC-25, ESC-TAR-21, ESC-MOR-45; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un operador de TEN-002 con permiso <code>cat.contratos.ver</code></li><li>Cuando Consulta por ID el contrato INT de Ana (TEN-001) y la ONT-DEMO-0001</li><li>Entonces 404 sin revelar existencia; los jobs <code>tec:aprovisionar</code> de TEN-002 no leen comandos de TEN-001; una copia COP-DEMO-001 lleva la configuración pero ni contratos ni precios aprobados (ESC-TEC-25, ESC-TAR-21, ESC-MOR-45).</li></ul><p><strong>CP-SRV-5007 — ESC-SRV-INT-07. (error) Hermano B solicita INT en el mismo domicilio</strong></p><ul><li>Cubre: ESC-SRV-INT-07; RN-CAT-030; relacionados: ESC-03; T12 §1.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha INT (T12 §1.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Hermano A con deuda ficticia en DIR-CASA-001</li><li>Cuando Hermano B solicita INT en el mismo domicilio</li><li>Entonces Se advierte la deuda del domicilio sin bloquear ni trasladarla (DEC-029; RN-CAT-030); el contrato de B se crea independiente (ESC-03 de M02).</li></ul><p><strong>CP-SRV-5008 — ESC-SRV-TEL-01. Se emite el ciclo de noviembre sin llamadas</strong></p><ul><li>Cubre: ESC-SRV-TEL-01; RN-CAT-075; T12 §2.7</li><li>Ola: O4 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Línea 0000-400101 de TEL-BAS con abono ficticio de ARS 8.000 y PRM-TAR-080 = false (ola O4, sin CDR)</li><li>Cuando Se emite el ciclo de noviembre sin llamadas</li><li>Entonces El comprobante tiene un solo renglón de abono por ARS 8.000 y ningún renglón de llamadas (RN-CAT-075).</li></ul><p><strong>CP-SRV-5009 — ESC-SRV-TEL-02. Se tasa una llamada local de 23:50 a 00:20</strong></p><ul><li>Cubre: ESC-SRV-TEL-02; relacionados: ESC-TAR-28; T12 §2.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Plan ficticio con banda A a ARS 10 por minuto hasta las 00:00 y banda B a ARS 5 por minuto después</li><li>Cuando Se tasa una llamada local de 23:50 a 00:20</li><li>Entonces Dos tramos: 10 min × 10 = ARS 100 y 20 min × 5 = ARS 100; neto ARS 200 con versión del plan en la traza (ESC-TAR-28).</li></ul><p><strong>CP-SRV-5010 — ESC-SRV-TEL-03. (error) Se ejecuta JOB-TEC-09</strong></p><ul><li>Cubre: ESC-SRV-TEL-03; RF-TEC-207, RF-TEC-213; T12 §2.7</li><li>Ola: O10 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado <code>cdr-demo.csv</code> contiene una llamada con origen 0000-400199, número sin línea vigente a la fecha</li><li>Cuando Se ejecuta JOB-TEC-09</li><li>Entonces La llamada queda como &quot;origen no encontrado&quot; (RF-TEC-207), no se tasa ni factura y aparece en el informe de no asignadas (RF-TEC-213).</li></ul><p><strong>CP-SRV-5011 — ESC-SRV-TEL-04. Se vuelve a importar el archivo</strong></p><ul><li>Cubre: ESC-SRV-TEL-04; RF-TEC-206; T12 §2.7</li><li>Ola: O10 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado El mismo <code>cdr-demo.csv</code> ya fue importado</li><li>Cuando Se vuelve a importar el archivo</li><li>Entonces La deduplicación (RF-TEC-206; PRM-TEC-108) no crea llamadas nuevas ni tasa dos veces; el resultado informa 50 duplicadas.</li></ul><p><strong>CP-SRV-5012 — ESC-SRV-TEL-05. Se intenta asignar el número a otro contrato el 20-11-2026</strong></p><ul><li>Cubre: ESC-SRV-TEL-05; RF-TEC-200; T12 §2.7</li><li>Ola: O10 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Línea 0000-400102 con baja confirmada el 15-11-2026</li><li>Cuando Se intenta asignar el número a otro contrato el 20-11-2026</li><li>Entonces Se rechaza: el número está en cuarentena (RF-TEC-200); las llamadas del 1 al 15 de noviembre se facturan en la factura final.</li></ul><p><strong>CP-SRV-5013 — ESC-SRV-TEL-06. (aislamiento) Importa un CDR cuyos orígenes coinciden con números de TEN-001</strong></p><ul><li>Cubre: ESC-SRV-TEL-06; T12 §2.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un usuario de TEN-002 con <code>tec.cdr.importar</code> (antes <code>tec.cdr.import</code>)</li><li>Cuando Importa un CDR cuyos orígenes coinciden con números de TEN-001</li><li>Entonces Ninguna llamada se atribuye a líneas de TEN-001; todas quedan &quot;origen no encontrado&quot; en TEN-002; consultar una llamada de TEN-001 por ID devuelve 404.</li></ul><p><strong>CP-SRV-5014 — ESC-SRV-TEL-07. Se importa el archivo PR1 del período</strong></p><ul><li>Cubre: ESC-SRV-TEL-07; RF-FAC-124; RN-TAR-099; T12 §2.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TEL (T12 §2.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Línea móvil revendida con factura del proveedor de ARS 9.500 (abono 7.000 + excedente 2.500)</li><li>Cuando Se importa el archivo PR1 del período</li><li>Entonces Renglones de abono y excedente en el comprobante del socio por ARS 9.500 con los conceptos del proveedor (RF-FAC-124; RN-TAR-099).</li></ul><p><strong>CP-SRV-5015 — ESC-SRV-TV-01. Se aplica el decodificador y el CAS confirma la activación el 01-12-2026</strong></p><ul><li>Cubre: ESC-SRV-TV-01; T12 §3.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado TV-BAS con abono ficticio de ARS 12.000 e instalación de ARS 6.000; decodificador con serie ficticia DECO-DEMO-0001 en custodia del instalador</li><li>Cuando Se aplica el decodificador y el CAS confirma la activación el 01-12-2026</li><li>Entonces El contrato pasa a <code>active</code>; el primer comprobante de diciembre suma ARS 18.000 (abono + instalación, DEC-016).</li></ul><p><strong>CP-SRV-5016 — ESC-SRV-TV-02. Se instala un segundo decodificador</strong></p><ul><li>Cubre: ESC-SRV-TV-02; T12 §3.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato TV-BAS activo con PRM-CAT-095 = 1 y punto adicional ficticio de ARS 2.000</li><li>Cuando Se instala un segundo decodificador</li><li>Entonces El período siguiente factura ARS 12.000 + ARS 2.000 = ARS 14.000; el segundo equipo queda en comodato con su constancia.</li></ul><p><strong>CP-SRV-5017 — ESC-SRV-TV-03. (error) El CAS rechaza la activación por serie no registrada</strong></p><ul><li>Cubre: ESC-SRV-TV-03; RF-TEC-188, RF-TEC-100; T12 §3.7</li><li>Ola: O3 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato en <code>pendingInstallation</code> con el decodificador aplicado</li><li>Cuando El CAS rechaza la activación por serie no registrada</li><li>Entonces EVT-TEC-21 <code>tec.provisioning.failed</code>; el contrato no se activa ni se factura; tarea manual (RF-TEC-188); la bandeja de instalaciones lo muestra como &quot;ejecutada sin activación&quot; (RF-TEC-100).</li></ul><p><strong>CP-SRV-5018 — ESC-SRV-TV-04. Se ejecuta la suspensión y luego se confirma el pago total</strong></p><ul><li>Cubre: ESC-SRV-TV-04; RF-MOR-122; T12 §3.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato TV con deuda vencida de ARS 24.000 y caso de mora aprobado</li><li>Cuando Se ejecuta la suspensión y luego se confirma el pago total</li><li>Entonces El CAS corta la señal (EVT-TEC-18); tras el pago, JOB-MOR-07 reconecta sin cargo y el contrato vuelve a <code>active</code> (RF-MOR-122).</li></ul><p><strong>CP-SRV-5019 — ESC-SRV-TV-05. El titular pide la baja desde la app</strong></p><ul><li>Cubre: ESC-SRV-TV-05; RF-TAR-115; RN-MOR-101; T12 §3.7</li><li>Ola: O3 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato TV activo con dos decodificadores</li><li>Cuando El titular pide la baja desde la app</li><li>Entonces Constancia por el mismo medio; el contrato pasa a <code>pendingTermination</code> y se genera la OT de retiro; si los equipos no se devuelven en 15 días, EVT-STK-07 abre un contacto en M09, sin cargo automático (HUE-INT-01). Con HUE-INT-01 corregido, el tenant puede habilitar el cargo por equipo no devuelto (RF-TAR-115, PRM-TAR-169, apagado por defecto), que se aprueba según RN-MOR-101.</li></ul><p><strong>CP-SRV-5020 — ESC-SRV-TV-06. (aislamiento) Busca la serie DECO-DEMO-0001 (TEN-001) en PAN-STK-11</strong></p><ul><li>Cubre: ESC-SRV-TV-06; T12 §3.7</li><li>Ola: O10 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O10 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha TV (T12 §3.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un operador de TEN-002</li><li>Cuando Busca la serie DECO-DEMO-0001 (TEN-001) en PAN-STK-11</li><li>Entonces Sin resultados; GET por ID devuelve 404.</li></ul><p><strong>CP-SRV-5021 — ESC-SRV-ELE-01. Lecturas validadas de 10.000 y 10.250 kWh</strong></p><ul><li>Cubre: ESC-SRV-ELE-01; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Suministro ELE-RES con cuadro ficticio tipo 2: cargo fijo ARS 3.000; 0–150 kWh a ARS 100; más de 150 kWh a ARS 120</li><li>Cuando Lecturas validadas de 10.000 y 10.250 kWh</li><li>Entonces Consumo 250 kWh; neto ARS 3.000 + 15.000 + 12.000 = ARS 30.000 con versión del cuadro y tramos en la traza; CAE obtenido.</li></ul><p><strong>CP-SRV-5022 — ESC-SRV-ELE-02. Se aprueba el balance (JOB-MED-15) y se emite</strong></p><ul><li>Cubre: ESC-SRV-ELE-02; RF-FIS-073; relacionados: ESC-TAR-11; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Suministro con contrato GD vigente, demanda 300 kWh e inyección 120 kWh (ESC-TAR-11)</li><li>Cuando Se aprueba el balance (JOB-MED-15) y se emite</li><li>Entonces Dos operaciones separadas con su IVA; si el total queda negativo, crédito registrado para la próxima factura (DEC-036, DEC-060; EVT-TAR-021) y datos de energía inyectada para RG 5746/2025 (RF-FIS-073).</li></ul><p><strong>CP-SRV-5023 — ESC-SRV-ELE-03. (error) Llega una lectura con inyección de 40 kWh</strong></p><ul><li>Cubre: ESC-SRV-ELE-03; RF-MED-099; RN-MED-078; relacionados: ESC-MED-18; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Punto sin contrato GD</li><li>Cuando Llega una lectura con inyección de 40 kWh</li><li>Entonces Excepción bloqueante (RF-MED-099; PRM-MED-089); el servicio queda &quot;observado&quot; en el lote y no se emite hasta resolver (RN-MED-078; ESC-MED-18).</li></ul><p><strong>CP-SRV-5024 — ESC-SRV-ELE-04. Corre JOB-MOR-02</strong></p><ul><li>Cubre: ESC-SRV-ELE-04; relacionados: ESC-MOR-17; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Suministro con electrodependencia acreditada y deuda vencida de ARS 90.000</li><li>Cuando Corre JOB-MOR-02</li><li>Entonces Evaluación <code>blocked</code>; ningún rol puede crear el caso de interrupción (ESC-MOR-17); la deuda sigue en gestión de aviso y convenio.</li></ul><p><strong>CP-SRV-5025 — ESC-SRV-ELE-05. Se calcula el período</strong></p><ul><li>Cubre: ESC-SRV-ELE-05; relacionados: ESC-TAR-08; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Gran usuario con reactiva alta (ejemplo M04 §9.3.6)</li><li>Cuando Se calcula el período</li><li>Entonces Renglón de factor de potencia con recargo ARS 209.677,42, método y tope en la traza; sin reactiva no hay renglón (ESC-TAR-08).</li></ul><p><strong>CP-SRV-5026 — ESC-SRV-ELE-06. El socio recarga ARS 5.000 desde la app</strong></p><ul><li>Cubre: ESC-SRV-ELE-06; relacionados: CU-POR-12; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Suministro prepago con deuda vencida y retención configurada del 10 %</li><li>Cuando El socio recarga ARS 5.000 desde la app</li><li>Entonces Capital acreditado ARS 4.500 y ARS 500 a cuenta de la deuda; token entregado (EVT-MED-23); factura de autogestión (CU-POR-12).</li></ul><p><strong>CP-SRV-5027 — ESC-SRV-ELE-07. Se ejecuta el corte remoto y luego se confirma el pago</strong></p><ul><li>Cubre: ESC-SRV-ELE-07; RF-MED-108; relacionados: CU-MED-08; T12 §4.7</li><li>Ola: O7 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Suministro telemedido con caso de mora <code>scheduled</code> en ventana hábil</li><li>Cuando Se ejecuta el corte remoto y luego se confirma el pago</li><li>Entonces <code>disconnect</code> y <code>reconnect</code> con <code>Idempotency-Key</code> (RF-MED-108); EVT-MED-21 en ambos; si falla, EVT-MED-22 y la OT no cierra (PRM-CAT-041; CU-MED-08).</li></ul><p><strong>CP-SRV-5028 — ESC-SRV-ELE-08. (aislamiento) Sincroniza un lote que incluye un punto de TEN-001 por ID</strong></p><ul><li>Cubre: ESC-SRV-ELE-08; relacionados: ESC-MED-24; T12 §4.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha ELE (T12 §4.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un lecturista de TEN-002</li><li>Cuando Sincroniza un lote que incluye un punto de TEN-001 por ID</li><li>Entonces Rechazo 404 por ítem; ninguna lectura de TEN-001 se crea ni se lee desde TEN-002 (ESC-MED-24).</li></ul><p><strong>CP-SRV-5029 — ESC-SRV-AG-01. Se aprueba un consumo de 20 m³</strong></p><ul><li>Cubre: ESC-SRV-AG-01; relacionados: ESC-TAR-01; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato AG-RES medido con TAR-AG-2026-11 (cargo fijo ARS 3.000; ARS 500 por m³)</li><li>Cuando Se aprueba un consumo de 20 m³</li><li>Entonces Neto ARS 13.000,00 con versión, fila y cantidad en la traza (ESC-TAR-01).</li></ul><p><strong>CP-SRV-5030 — ESC-SRV-AG-02. Se calcula el período</strong></p><ul><li>Cubre: ESC-SRV-AG-02; relacionados: ESC-TAR-09; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato no medido tipo 15 con TBM 1.000, zonal 0,9, coeficiente 1,1 y cuota 500</li><li>Cuando Se calcula el período</li><li>Entonces red2(1.000 × 0,9 × 1,1 + 500 × 0,7) = ARS 1.340,00 (ESC-TAR-09).</li></ul><p><strong>CP-SRV-5031 — ESC-SRV-AG-03. (error) Se calcula el lote</strong></p><ul><li>Cubre: ESC-SRV-AG-03; relacionados: ESC-TAR-09, ESC-TAR-15; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato no medido tipo 15 cuyo inmueble tiene TBM = 0</li><li>Cuando Se calcula el lote</li><li>Entonces La cuenta se excluye con <code>TAR-E-WATER-TBM</code> y el lote continúa (ESC-TAR-09, ESC-TAR-15).</li></ul><p><strong>CP-SRV-5032 — ESC-SRV-AG-04. Corre la evaluación de mora</strong></p><ul><li>Cubre: ESC-SRV-AG-04; relacionados: ESC-MOR-15; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Cuenta unificada con agua ARS 13.000, electricidad ARS 20.000 y cementerio ARS 7.000 vencidos; pago de ARS 8.000</li><li>Cuando Corre la evaluación de mora</li><li>Entonces Decisión por servicio, sin corte automático; la deuda de cementerio no habilita suspender agua ni electricidad (ESC-MOR-15; PA-MOR-08).</li></ul><p><strong>CP-SRV-5033 — ESC-SRV-AG-05. Se ejecuta la distribución (JOB-MED-07)</strong></p><ul><li>Cubre: ESC-SRV-AG-05; relacionados: CU-MED-06; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Consorcio con medidor general de 100 m³ y cuatro unidades funcionales con coeficiente 0,25</li><li>Cuando Se ejecuta la distribución (JOB-MED-07)</li><li>Entonces 25 m³ por unidad; cada contrato se factura con su consumo distribuido y la traza al medidor general (CU-MED-06).</li></ul><p><strong>CP-SRV-5034 — ESC-SRV-AG-06. Ana informa una autolectura que da 95 m³</strong></p><ul><li>Cubre: ESC-SRV-AG-06; relacionados: CU-POR-11; T12 §5.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Ventana de autolectura abierta; último consumo 18 m³</li><li>Cuando Ana informa una autolectura que da 95 m³</li><li>Entonces La autolectura queda &quot;En revisión&quot; por fuera de rango, sin consumo aprobado (CU-POR-11; EVT-MED-27).</li></ul><p><strong>CP-SRV-5035 — ESC-SRV-AG-07. (aislamiento) Busca por nomenclatura un inmueble de TEN-001</strong></p><ul><li>Cubre: ESC-SRV-AG-07; RF-PER-092; T12 §5.7</li><li>Ola: O2 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O2 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha AG (T12 §5.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un operador de TEN-002</li><li>Cuando Busca por nomenclatura un inmueble de TEN-001</li><li>Entonces Sin resultados; la validación de parcela duplicada (RF-PER-092) solo compara dentro del tenant.</li></ul><p><strong>CP-SRV-5036 — ESC-SRV-CLO-01. Se aprueba un consumo AG de 20 m³ y se calcula el período</strong></p><ul><li>Cubre: ESC-SRV-CLO-01; RN-TAR-015; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Cuenta con AG y CLO; CLO tiene servicio relacionado AG (PRM-CAT-080); cuadro ficticio: cargo fijo ARS 1.000 y ARS 200 por m³</li><li>Cuando Se aprueba un consumo AG de 20 m³ y se calcula el período</li><li>Entonces CLO = 1.000 + 20 × 200 = ARS 5.000,00, con la traza al consumo AG de origen (RN-TAR-015).</li></ul><p><strong>CP-SRV-5037 — ESC-SRV-CLO-02. Se recalcula CLO de noviembre</strong></p><ul><li>Cubre: ESC-SRV-CLO-02; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PRM-TAR-061 = true; el consumo AG de octubre ya se liquidó en CLO</li><li>Cuando Se recalcula CLO de noviembre</li><li>Entonces Solo se toma el consumo AG no liquidado; octubre no se vuelve a cobrar.</li></ul><p><strong>CP-SRV-5038 — ESC-SRV-CLO-03. Se da de alta AG</strong></p><ul><li>Cubre: ESC-SRV-CLO-03; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un socio pide el alta de AG en un inmueble con red cloacal</li><li>Cuando Se da de alta AG</li><li>Entonces No se crea ningún contrato CLO; CLO requiere su propia solicitud (M02 6.C.6).</li></ul><p><strong>CP-SRV-5039 — ESC-SRV-CLO-04. Se facturan las 12 cuotas</strong></p><ul><li>Cubre: ESC-SRV-CLO-04; RN-TAR-074; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Plan de obra cloacal ficticio de ARS 100.000 en 12 cuotas</li><li>Cuando Se facturan las 12 cuotas</li><li>Entonces Cuotas 1 a 11 de ARS 8.333,33 y última de ARS 8.333,37 (ajuste de saldo, RN-TAR-074).</li></ul><p><strong>CP-SRV-5040 — ESC-SRV-CLO-05. (error) Se calcula el lote</strong></p><ul><li>Cubre: ESC-SRV-CLO-05; RN-TAR-070; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato tipo 17 sin tipo de obra informado</li><li>Cuando Se calcula el lote</li><li>Entonces La cuenta se excluye con <code>TAR-E-WORKS-TYPE</code> y el lote continúa (RN-TAR-070).</li></ul><p><strong>CP-SRV-5041 — ESC-SRV-CLO-06. Se importa (RF-MED-055)</strong></p><ul><li>Cubre: ESC-SRV-CLO-06; RF-MED-055; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Archivo ARR de consumos directos de cloaca</li><li>Cuando Se importa (RF-MED-055)</li><li>Entonces Los consumos quedan pendientes de aprobación; no se liquidan hasta aprobarlos.</li></ul><p><strong>CP-SRV-5042 — ESC-SRV-CLO-07. (aislamiento) Se calcula</strong></p><ul><li>Cubre: ESC-SRV-CLO-07; T12 §6.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha CLO (T12 §6.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un contrato CLO de TEN-002 con servicio relacionado AG</li><li>Cuando Se calcula</li><li>Entonces Solo toma consumos AG de la misma cuenta de TEN-002; nunca los de TEN-001, aunque coincida la nomenclatura.</li></ul><p><strong>CP-SRV-5043 — ESC-SRV-GAS-01. Se aprueba una lectura de 100 m³ con presión 1,0140 y temperatura 0,9870</strong></p><ul><li>Cubre: ESC-SRV-GAS-01; relacionados: ESC-TAR-10; T12 §7.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato GAS-RES; factor del período 9.300 kcal/m³; óptimo 9.300; coeficiente 1; PRM-TAR-051 = <code>round0</code>; cuadro ficticio con cargo fijo ARS 2.500 y ARS 300 por m³</li><li>Cuando Se aprueba una lectura de 100 m³ con presión 1,0140 y temperatura 0,9870</li><li>Entonces red4(100 × 1,0140 × 0,9870) = 100,0818 m³ → 100 m³ corregidos; neto = 2.500 + 100 × 300 = ARS 32.500,00, con factores y método en la traza (ESC-TAR-10).</li></ul><p><strong>CP-SRV-5044 — ESC-SRV-GAS-02. (error) Se valida y se calcula</strong></p><ul><li>Cubre: ESC-SRV-GAS-02; RN-TAR-035; relacionados: ESC-MED-17, ESC-TAR-10; T12 §7.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado No hay factor calórico de noviembre (ni por categoría ni general)</li><li>Cuando Se valida y se calcula</li><li>Entonces El consumo queda aprobado con su volumen medido y M04 excluye la cuenta con <code>TAR-E-GAS-FACTOR</code>; el lote continúa (RN-TAR-035, DEC-085; ESC-MED-17, ESC-TAR-10; antes &quot;el consumo queda bloqueado por falta factor de gas&quot;).</li></ul><p><strong>CP-SRV-5045 — ESC-SRV-GAS-03. Se intenta habilitar el contrato</strong></p><ul><li>Cubre: ESC-SRV-GAS-03; relacionados: CU-ESP-GAS; T12 §7.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado PRM-CAT-096 = true; la solicitud tiene certificado del matriculado pero no DDJJ de artefactos</li><li>Cuando Se intenta habilitar el contrato</li><li>Entonces Se rechaza la habilitación; el contrato no pasa a Activo hasta cargar la DDJJ (PAN-CAT-25) y aprobar la inspección (CU-ESP-GAS).</li></ul><p><strong>CP-SRV-5046 — ESC-SRV-GAS-04. El socio paga los ARS 45.000</strong></p><ul><li>Cubre: ESC-SRV-GAS-04; RF-CAT-066; RN-MOR-086; T12 §7.7</li><li>Ola: O6 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O6 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Contrato suspendido por mora con deuda de ARS 45.000</li><li>Cuando El socio paga los ARS 45.000</li><li>Entonces Estado &quot;Rehabilitación en trámite&quot;; se genera una OT de inspección y el contrato vuelve a Activo solo con la inspección aprobada (RN-MOR-086; RF-CAT-066).</li></ul><p><strong>CP-SRV-5047 — ESC-SRV-GAS-05. El bot clasifica el mensaje</strong></p><ul><li>Cubre: ESC-SRV-GAS-05; RF-CRM-122; T12 §7.7</li><li>Ola: O3 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado El socio escribe al bot &quot;huele a gas en la cocina&quot;</li><li>Cuando El bot clasifica el mensaje</li><li>Entonces Caso de urgencia crítica, aviso inmediato a la guardia y mensaje de seguridad con teléfono de emergencia; el bot no da instrucciones técnicas (RF-CRM-122).</li></ul><p><strong>CP-SRV-5048 — ESC-SRV-GAS-06. Se abre un caso de inspección</strong></p><ul><li>Cubre: ESC-SRV-GAS-06; RF-TEC-176, RF-TEC-180; T12 §7.7</li><li>Ola: O7 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Un lecturista informa un precinto roto</li><li>Cuando Se abre un caso de inspección</li><li>Entonces El caso nace como <code>suspected</code>; el recupero solo se factura con método aprobado y aprobación explícita, nunca de forma automática (RF-TEC-176, 180).</li></ul><p><strong>CP-SRV-5049 — ESC-SRV-GAS-07. (aislamiento) TEN-002 calcula su lote de gas</strong></p><ul><li>Cubre: ESC-SRV-GAS-07; RN-TAR-035; T12 §7.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha GAS (T12 §7.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado TEN-001 tiene cargado el factor de noviembre y TEN-002 no</li><li>Cuando TEN-002 calcula su lote de gas</li><li>Entonces TEN-002 no usa el factor de TEN-001; sus cuentas de gas quedan excluidas con <code>TAR-E-GAS-FACTOR</code> (RN-TAR-035, DEC-085; antes &quot;sus consumos quedan bloqueados por falta de factor&quot;).</li></ul><p><strong>CP-SRV-5050 — ESC-SRV-ALU-01. Se da de alta un contrato ELE-RES en la localidad alcanzada</strong></p><ul><li>Cubre: ESC-SRV-ALU-01; RN-CAT-035; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Regla ELE → ALU en modo <code>create</code> con <code>legalBasis</code> (ordenanza ficticia 100/2026)</li><li>Cuando Se da de alta un contrato ELE-RES en la localidad alcanzada</li><li>Entonces JOB-CAT-01 crea el contrato ALU con <code>parentContractId</code> del ELE y el grupo de facturación por defecto (RN-CAT-035).</li></ul><p><strong>CP-SRV-5051 — ESC-SRV-ALU-02. Se da de alta el ELE</strong></p><ul><li>Cubre: ESC-SRV-ALU-02; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Regla en modo <code>propose</code> (sin fundamento normativo)</li><li>Cuando Se da de alta el ELE</li><li>Entonces Se crea una propuesta pendiente de consentimiento del socio; no se crea el contrato (DEC-023).</li></ul><p><strong>CP-SRV-5052 — ESC-SRV-ALU-03. JOB-CAT-01 lo vuelve a evaluar</strong></p><ul><li>Cubre: ESC-SRV-ALU-03; RN-CAT-036; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado El evento de alta del ELE se reprocesa por un reintento</li><li>Cuando JOB-CAT-01 lo vuelve a evaluar</li><li>Entonces No se crea un segundo ALU (idempotencia <code>(eventId, ruleId)</code>; RN-CAT-036).</li></ul><p><strong>CP-SRV-5053 — ESC-SRV-ALU-04. Se calcula un ELE con 250 kWh</strong></p><ul><li>Cubre: ESC-SRV-ALU-04; relacionados: ESC-TAR-13; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Regla <code>tasa_alumbrado</code> = consumo × 0,85 y beneficio social del 50 %; el socio está inscripto en tarifa social</li><li>Cuando Se calcula un ELE con 250 kWh</li><li>Entonces Tasa ARS 212,50 y bonificación −ARS 106,25, con la referencia entre reglas en la traza (ESC-TAR-13).</li></ul><p><strong>CP-SRV-5054 — ESC-SRV-ALU-05. (error) Se emite la factura de noviembre</strong></p><ul><li>Cubre: ESC-SRV-ALU-05; RF-FAC-120, RF-FIS-134; T12 §8.7</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado El convenio con el municipio venció el 31-10-2026</li><li>Cuando Se emite la factura de noviembre</li><li>Entonces El ítem de alumbrado queda bloqueado como excepción, y el resto de la factura sigue su curso según la política (RF-FAC-120; RF-FIS-134).</li></ul><p><strong>CP-SRV-5055 — ESC-SRV-ALU-06. El socio paga ARS 5.000</strong></p><ul><li>Cubre: ESC-SRV-ALU-06; RF-FIS-138; RN-CON-066; T12 §8.7</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Factura de ARS 10.000 con ARS 1.000 de alumbrado de terceros</li><li>Cuando El socio paga ARS 5.000</li><li>Entonces Se imputan ARS 500 al tercero por prorrata; se emite EVT-FIS-16 y M15 registra el pasivo (RF-FIS-138; RN-CON-066).</li></ul><p><strong>CP-SRV-5056 — ESC-SRV-ALU-07. Se aprueba la rendición</strong></p><ul><li>Cubre: ESC-SRV-ALU-07; RF-FIS-139; T12 §8.7</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Cobros de alumbrado de octubre por ARS 800.000 con comisión del 3 %</li><li>Cuando Se aprueba la rendición</li><li>Entonces Neto a rendir ARS 776.000; EVT-FIS-17 genera la orden de pago en M14 y cancela el pasivo (RF-FIS-139).</li></ul><p><strong>CP-SRV-5057 — ESC-SRV-ALU-08. M10 ejecuta la desconexión</strong></p><ul><li>Cubre: ESC-SRV-ALU-08; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado Se da de baja el ELE principal</li><li>Cuando M10 ejecuta la desconexión</li><li>Entonces Se emite EVT-TEC-20 y el ALU dependiente se da de baja con el principal (M02 6.C.8).</li></ul><p><strong>CP-SRV-5058 — ESC-SRV-ALU-09. (aislamiento) TEN-002 emite una factura con alumbrado</strong></p><ul><li>Cubre: ESC-SRV-ALU-09; T12 §8.7</li><li>Ola: O7 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O7 desplegada; tenant ficticio TEN-001 y TEN-002; configuración de la ficha ALU (T12 §8.2).</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado TEN-001 tiene un convenio vigente con Municipalidad Demo</li><li>Cuando TEN-002 emite una factura con alumbrado</li><li>Entonces TEN-002 no ve ni usa el convenio de TEN-001; sin convenio propio, el ítem queda bloqueado.</li></ul>',121)])])}const T=i(n,[["render",c]]);export{p as __pageData,T as default};
